  --argjson public_launch_ready "$PUBLIC_LAUNCH_READY" \
  --argjson artifact_count "$ARTIFACT_COUNT" \
  --slurpfile checks "$CHECK_RESULTS" \
  --slurpfile failures "$FAILURE_RESULTS" \
