m_semantics_classic_playtest_runner_status_semantics_classic_playtest_launcher_semantics_classic_playtest_handoff_readiness_semantics_classic_playtest_handoff_packet_semantics_classic_playtest_handoff_packet_markdown_semantics_classic_playtest_readiness_semantics_full_screen_ui_replication_semantics_shell_meta_ui_replication_semantics_match_setup_ui_replication_semantics_campaign_outcome_ui_readiness_semantics_campaign_ui_continuity_semantics_campaign_ui_continuity_ppm_semantics_in_match_hud_state_replication_semantics_session_state_continuity_semantics_combat_readability_pressure_readiness_semantics_classic_rts_camera_minimap_sync_semantics_classic_rts_camera_minimap_sync_ppm_semantics_classic_rts_control_loop_semantics_classic_rts_selection_minimap_semantics_classic_rts_build_lifecycle_semantics_classic_rts_tech_tree_semantics_classic_rts_projectile_ability_semantics_first_minute_command_feedback_replay_semantics_first_minute_command_feedback_rejection_replay_semantics_bot_executor_source_chain_semantics_bot_executor_failure_recovery_matrix_semantics_and_bot_gap_foundation_micro_intel_semantics",
    artifact_count: $artifact_count,
    checks: $checks,
    failures: $failures,
    reviewer_next_action: (if $green and $public_launch_ready then "review_public_launch_ready_evidence" elif $green then "collect_real_external_public_launch_evidence" else "regenerate_or_repair_release_review_packet" end)
  }' >"$SUMMARY_FILE"

case "$STATUS" in
  release_review_packet_integrity_green)
    printf 'TRILLIONNIUM_WORLD_RELEASE_REVIEW_PACKET_INTEGRITY_GREEN %s\n' "$SUMMARY_FILE"
    ;;
  release_review_packet_integrity_green_with_public_launch_blockers)
